const classifyPrompt = 'Kamu adalah classifier konten audio/video. Analisis transkrip berikut.\n\nTRANSKRIP:\n"""\n' + fullText + '\n"""\n\nNAMA FILE/MEETING: ' + meetingName + '\n\nTENTUKAN content_class - pilih SATU:\n- "meeting": diskusi grup (2+ orang)\n- "one_on_one": percakapan PRIVAT 2 orang\n- "non_meeting": konten untuk dikonsumsi (podcast, YouTube, kuliah)\n\nEDGE CASE - 2 orang:\n- Ada sinyal audiens -> non_meeting\n- Bersifat privat, evaluatif -> one_on_one\n\nTIPE SPESIFIK: meeting: standup|client_meeting|retrospective|planning|brainstorm|all_hands | one_on_one: interview|counseling|client_pitch|performance_review|mentoring | non_meeting: philosophy|science|educational_interview|podcast|lecture|comedy|casual_discussion\n\nSHOULD_PROCESS = false HANYA jika transkrip kosong atau noise murni.\n\nKEMBALIKAN JSON MURNI:' + JSON.stringify(classifySchema);

const classify_body = {model:'vertex_ai/openai/gpt-oss-120b-maas',messages:[{role:'user',content:classifyPrompt}],temperature:0.1,max_tokens:1500,response_format:{type:'json_object'}};

return [{
  json: {
    text: fullText,
    total_chunks: chunkData.length,
    merge_status: 'complete',
    classify_body: classify_body
  },
  pairedItem: { item: 0 }
}];

const driveLink = ($json.drive_link || '').trim();
const meetingName = $json.meeting_name || '';

const patterns = [
  /\/d\/([a-zA-Z0-9_-]{20,})/,
  /[?&]id=([a-zA-Z0-9_-]{20,})/,
];

let fileId = null;
for (const pattern of patterns) {
  const match = driveLink.match(pattern);
  if (match) { fileId = match[1]; break; }
}

if (!fileId) {
  throw new Error('Format link Google Drive tidak dikenali. Gunakan link Share: klik kanan file > Share > Copy link.');
}

const downloadUrl = 'https://drive.usercontent.google.com/download?id=' + fileId + '&export=download&confirm=t&authuser=0';

return [{ json: { file_id: fileId, download_url: downloadUrl, meeting_name: meetingName } }];

const recording = $binary.recording || $binary.data;

if (!recording) {
  throw new Error('Download dari Google Drive gagal. Tidak ada data yang diterima.');
}

if (recording.mimeType && recording.mimeType.includes('text/html')) {
  throw new Error('Google Drive mengembalikan halaman error. Pastikan file di-share dengan setting "Anyone with the link can view".');
}

const meetingName = $('Extract Drive ID').first().json.meeting_name || '';

return [{ json: { meeting_name: meetingName }, binary: { recording: recording } }];

const d = $('Parse AI Response').first().json;
const notionUrl = '';
const rawEmails = ($('Upload Meeting Recording').first().json?.email_penerima || '').trim();
const to = rawEmails.split(',').map(e => e.trim()).filter(Boolean);
if (to.length === 0) return [];

const lang = $('Parse Classifier Output').first().json?.language || 'id';
