const participants = Array.isArray(d.participants) ? d.participants.join(', ') : (d.participants || '-');

const renderList = (arr, fn) => Array.isArray(arr) && arr.length ? arr.map(fn).join('') : '';
const decisions = renderList(d.key_decisions, k => '<li>' + (typeof k === 'string' ? k : (k.decision || k.description || JSON.stringify(k))) + '</li>');
const actions = renderList(d.action_items, a => {
  if (typeof a === 'string') return '<li>' + a + '</li>';
  const task = a.task || a.description || a.item || JSON.stringify(a);
  const meta = [a.assignee && 'PIC: ' + a.assignee, a.owner && 'PIC: ' + a.owner, a.deadline && 'Deadline: ' + a.deadline, a.due_date && 'Due: ' + a.due_date].filter(Boolean).join(' Â· ');
  return '<li><strong>' + task + '</strong>' + (meta ? '<br><small style="color:#64748b">' + meta + '</small>' : '') + '</li>';
});

const introText = lang === 'id'
  ? 'Halo, berikut adalah notulen otomatis untuk meeting <b>\'' + title + '\'</b> pada ' + date + '. File teks lengkap tersedia di lampiran email ini.'
  : 'Hello, here are the automated meeting notes for <b>\'' + title + '\'</b> on ' + date + '. The full plain-text version is attached to this email.';

const html = '<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="font-family:-apple-system,sans-serif;max-width:600px;margin:0 auto;padding:24px;color:#1e293b">'
