  + '<h3>Ringkasan Eksekutif</h3><p style="line-height:1.6">' + (d.executive_summary || '-') + '</p>'
  + (decisions ? '<h3>Keputusan</h3><ul>' + decisions + '</ul>' : '')
  + (actions ? '<h3>Action Items</h3><ul>' + actions + '</ul>' : '')
  + (notionUrl ? '<div style="margin-top:24px;padding:16px;background:#eff6ff;border-radius:8px"><a href="' + notionUrl + '" style="color:#3b82f6;font-weight:600;text-decoration:none">Lihat Notulen Lengkap di Notion</a></div>' : '')
  + '<hr style="margin-top:32px;border:none;border-top:1px solid #e2e8f0"><p style="color:#94a3b8;font-size:12px;text-align:center">Dibuat otomatis oleh Meeting Notes AI Â· File .md terlampir</p>'
  + '</body></html>';

const lines = [];
lines.push('NOTULEN MEETING');
lines.push('===============');
lines.push('');
lines.push('Judul    : ' + title);
lines.push('Tanggal  : ' + date);
lines.push('Peserta  : ' + participants);
lines.push('');
lines.push('');
lines.push('RINGKASAN EKSEKUTIF');
lines.push('-------------------');
lines.push(d.executive_summary || '-');
lines.push('');

if (Array.isArray(d.discussion_topics) && d.discussion_topics.length) {
  lines.push('');
  lines.push('TOPIK DISKUSI');
